function feedback(result){if(result?.ok===false)audio.event('denied');else if(result?.count>0)audio.event('purchase');if(result?.message)toast(result.message);if(result?.action==='staff')openStaff();updateUI();return result;}
function persist(){if(sim.state.mode==='intro')return;try{localStorage.setItem(SAVE,JSON.stringify(sim.snapshot()));}catch{}}
function clearInputs(){keys.clear();sources.clear();stick={x:0,y:0};if(stickDriving&&sim.state.engine)sim.setThrottle(0);stickDriving=false;reelToggle=false;for(const p of pointers)p.reset();$('stick-thumb').style.transform='';sim.cancelCast();castOwner=null;}
