 $('game-state').textContent=JSON.stringify({...sim.publicState(),camera:world.publicState().camera,audio:audio.publicState(),ecology:world.publicState().wildlife,menu,rendererFPS:Math.round(fps),viewport:{width:innerWidth,height:innerHeight},build:'20260927-pixel-v5.1'});
