function frame(now){const dt=Math.min(.1,Math.max(0,(now-lastFrame)/1000));lastFrame=now;sim.step(dt,input());world.draw(sim.state,dt);updateWorldActions();audio.update(sim.state.time,sim.state.engine&&!sim.state.paused,sim.state.throttle,sim.state.walking&&!sim.state.paused,{speed:Math.abs(sim.state.speed),wave:sea.waveHeight,underwater:sim.state.mode==='swim'&&sim.state.swim?.y<-.2,strain:sim.state.tension/100,slipping:sim.state.fishState==='fight'&&!sim.state.reeling&&!sim.state.paused,roll:sim.state.roll,reeling:sim.state.reeling&&!sim.state.paused});uiElapsed+=dt;saveElapsed+=dt;fpsTimer+=dt;frames++;if(fpsTimer>1){fps=frames/fpsTimer;frames=0;fpsTimer=0;}if(uiElapsed>.1){uiElapsed=0;updateUI();}if(saveElapsed>10){saveElapsed=0;persist();}requestAnimationFrame(frame);}
