const mcp=document.modelContext;if(mcp?.registerTool){const ctl=new AbortController(),reg=tool=>{try{Promise.resolve(mcp.registerTool(tool,{signal:ctl.signal})).catch(()=>{});}catch{}};reg({name:'read_pixel_fishing_state',title:'读取像素海钓状态',description:'Read current trip state, active real-time seconds, and controls. No changes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({...sim.publicState(),camera:world.publicState().camera,audio:audio.publicState(),ecology:world.publicState().wildlife,menu,fps:Math.round(fps)})});reg({name:'pixel_fishing_action',title:'像素海钓操作',description:'Perform the same validated player action as the visible game controls, without advancing time. Menus pause the game.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['start','resume','close','walk_counter','walk_boarding','interact','pack','launch','engine','anchor','cast_start','cast_release','hook','retrieve','reel_on','reel_off','keep','release','trade','swim','climb']},destination:{type:'string'}},required:['action'],additionalProperties:false},execute:({action})=>{let result;if(action==='start'||action==='resume'){start(action==='resume');return sim.publicState();}if(action==='close'){closeModal();return sim.publicState();}if(['pack','trade'].includes(action)){result=action==='pack'?sim.packStarter():sim.trade();}else if(['keep','release'].includes(action)){result=action==='keep'?sim.keepCatch():sim.releaseCatch();if(result.ok)closeModal();}else{if(menu)throw Error('Close the current menu first.');const actions={walk_counter:()=>sim.walkTo('counter'),walk_boarding:()=>sim.walkTo('boarding'),interact:()=>sim.interact(),launch:()=>sim.launchBoat(),engine:()=>sim.toggleEngine(),anchor:()=>sim.toggleAnchor(),cast_start:()=>sim.startCast(),cast_release:()=>sim.releaseCast(),hook:()=>sim.hook(),retrieve:()=>sim.retrieve(),reel_on:()=>{reelToggle=true;return{ok:true};},reel_off:()=>{reelToggle=false;return{ok:true};},swim:()=>sim.jump(),climb:()=>sim.reboard()};result=actions[action]?.();}feedback(result);persist();return{result,...sim.publicState()};}});reg({name:'set_pixel_fishing_waypoint',title:'选择像素海钓航向',description:'Choose a chart fishing spot or the return dock. Real-time boating physics and collision rules apply.',inputSchema:{type:'object',properties:{destination:{type:'string',enum:['0','1','2','3','dock']}},required:['destination'],additionalProperties:false},execute:({destination})=>{if(menu)throw Error('Close chart/menu first.');const result=feedback(sim.selectWaypoint(destination==='dock'?'dock':FISHING_SPOTS[Number(destination)]));return{result,...sim.publicState()};}});window.addEventListener('pagehide',()=>ctl.abort(),{once:true});}
